import{_ as e,o as a,c as n,ag as t}from"./chunks/framework.CHxxV8OH.js";const u=JSON.parse('{"title":"Core Concepts","description":"","frontmatter":{"prev":{"text":"Quick Start","link":"/quick-start"},"next":{"text":"Creating Agents","link":"/creating-agents"}},"headers":[],"relativePath":"core-concepts.md","filePath":"core-concepts.md","lastUpdated":1775890242000}'),i={name:"core-concepts.md"};function l(o,s,r,p,c,d){return a(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h1><p>Agent Studio is built on a few core ideas. Understanding these makes everything else intuitive.</p><h2 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h2><p>An <strong>agent</strong> is a specialized entity that performs tasks within constraints you define.</p><p><strong>Key properties:</strong></p><ul><li><strong>Identity</strong>: Name, emoji, role, background</li><li><strong>Instructions</strong>: How the agent should behave (markdown)</li><li><strong>Capabilities</strong>: Which tools, skills, and MCP servers it can access</li><li><strong>Handoffs</strong>: Which other agents it can delegate to</li></ul><p><strong>Agents are:</strong></p><ul><li>Stored as <code>.agent.md</code> files (human-readable, version-controlled)</li><li>Discoverable by Agent Studio automatically</li><li>Shareable with your team via git</li><li>Composable with other agents through handoffs</li></ul><p><strong>Examples:</strong></p><ul><li><code>DataAnalyst</code>: Specializes in SQL, statistics, and visualizations</li><li><code>APIClient</code>: Handles REST APIs and data fetching</li><li><code>ReportWriter</code>: Creates formatted documents and summaries</li></ul><h2 id="workflows" tabindex="-1">Workflows <a class="header-anchor" href="#workflows" aria-label="Permalink to &quot;Workflows&quot;">​</a></h2><p>A <strong>workflow</strong> is a sequence of agents executing tasks in order, passing results from one to the next.</p><p><strong>Key properties:</strong></p><ul><li><strong>Steps</strong>: List of agents in execution order</li><li><strong>Entry point</strong>: Where the workflow starts receiving input</li><li><strong>Exit point</strong>: Where final results are collected</li><li><strong>Trigger</strong>: Manual, webhook, or scheduled (future)</li></ul><p><strong>Workflows are:</strong></p><ul><li>Visual (drag-and-drop on a canvas)</li><li>Executable from VS Code chat</li><li>Version-controlled as <code>.json</code> files</li><li>Testable and debuggable</li></ul><p><strong>Example workflow:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[User Input]</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>[DataFetcher Agent] → retrieves data from API</span></span>
<span class="line"><span>  ↓ (output: raw data)</span></span>
<span class="line"><span>[DataCleaner Agent] → validates and transforms</span></span>
<span class="line"><span>  ↓ (output: clean dataset)</span></span>
<span class="line"><span>[Analyst Agent] → generates insights</span></span>
<span class="line"><span>  ↓ (output: report)</span></span>
<span class="line"><span>[ReportFormatter Agent] → beautifies for presentation</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>[Final Report]</span></span></code></pre></div><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><p>A <strong>tool</strong> is a discrete, reusable function that agents can call.</p><p><strong>Examples:</strong></p><ul><li><code>fetch_http</code>: Call an API endpoint</li><li><code>query_sql</code>: Execute a SQL query against a database</li><li><code>read_file</code>: Open and read a file from disk</li><li><code>send_email</code>: Send an email message</li><li><code>parse_json</code>: Parse JSON strings into structured data</li></ul><p><strong>Tools are:</strong></p><ul><li>Registered in a directory your workspace points to</li><li>Reusable across multiple agents</li><li>Discovered and managed through the Capabilities Inspector</li><li>Implemented in any language (JavaScript, Python, Go, etc.)</li></ul><p><strong>Key rule</strong>: Agents don&#39;t implement tools; they request tools they&#39;ve been assigned.</p><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><p>A <strong>skill</strong> is a collection of related instructions, templates, or knowledge an agent inherits.</p><p><strong>Examples:</strong></p><ul><li><code>CompanyDataModel</code>: Documentation of your company&#39;s database schema and query patterns</li><li><code>BestPractices</code>: Style guidelines, error handling patterns, security rules</li><li><code>EmailTemplates</code>: Reusable email formats and structures</li></ul><p><strong>Skills are:</strong></p><ul><li>Stored as <code>.md</code> files in a <code>.skills</code> directory</li><li>Assigned to agents to give them context</li><li>Shared across multiple agents</li><li>Version-controlled like regular code</li></ul><p><strong>How they work</strong>: When you assign a Skill to an agent, its contents are automatically included in the agent&#39;s context when it runs.</p><h2 id="mcp-servers" tabindex="-1">MCP Servers <a class="header-anchor" href="#mcp-servers" aria-label="Permalink to &quot;MCP Servers&quot;">​</a></h2><p>An <strong>MCP Server</strong> (Model Context Protocol) is an external service providing resources, tools, or prompts to agents.</p><p><strong>Examples:</strong></p><ul><li>An API server exposing database queries as MCP resources</li><li>A document service providing knowledge base access</li><li>A custom business logic service with specialized tools</li></ul><p><strong>MCP Servers are:</strong></p><ul><li>Connected via HTTP endpoints</li><li>Auto-discovered and managed through the Capabilities Inspector</li><li>Assignable to specific agents or shared globally</li><li>Real-time (health checks, latency monitoring)</li></ul><p><strong>Key difference from Tools</strong>: MCP Servers are external services; Tools are functions agents call directly.</p><h2 id="handoffs" tabindex="-1">Handoffs <a class="header-anchor" href="#handoffs" aria-label="Permalink to &quot;Handoffs&quot;">​</a></h2><p>A <strong>handoff</strong> is a delegation relationship between two agents.</p><p><strong>How it works:</strong></p><ul><li>Agent A has a task it can&#39;t complete alone</li><li>Agent A asks Agent B to handle part of the task</li><li>Agent B performs its part and returns results</li><li>Agent A continues or concludes</li></ul><p><strong>Handoff properties:</strong></p><ul><li><strong>Direction</strong>: Which agent delegates to which</li><li><strong>Constraints</strong>: <ul><li>Requires approval (human-in-the-loop)</li><li>Max retries (if delegation fails)</li><li>Timeout (how long to wait)</li></ul></li></ul><p><strong>Example:</strong></p><ul><li><code>DataAnalyst</code> receives: &quot;Analyze this dataset and create a presentation&quot;</li><li>It can analyze data itself</li><li>It needs a visualization: handoff to <code>ChartBuilder</code></li><li>It needs a document: handoff to <code>PresentationWriter</code></li><li>It collects results and delivers the final presentation</li></ul><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><p>A <strong>capability</strong> is the union of tools, skills, and MCP servers an agent has access to.</p><p><strong>The Capabilities Inspector shows:</strong></p><ul><li>All available tools, skills, and MCP servers</li><li>Which agents use each capability</li><li>Gaps (tools that no agent can access)</li><li>Overrides (tools assigned to too many agents)</li></ul><p><strong>Why it matters</strong>: Clarity. At a glance, you see exactly what infrastructure exists and who needs it.</p><h2 id="the-execution-flow" tabindex="-1">The Execution Flow <a class="header-anchor" href="#the-execution-flow" aria-label="Permalink to &quot;The Execution Flow&quot;">​</a></h2><p>Here&#39;s how Agent Studio works from user action to completion:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│ You ask an agent a question in chat     │</span></span>
<span class="line"><span>└────────────────────┬────────────────────┘</span></span>
<span class="line"><span>                     ↓</span></span>
<span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│ Agent&#39;s context is built:               │</span></span>
<span class="line"><span>│ - Identity                              │</span></span>
<span class="line"><span>│ - Instructions                          │</span></span>
<span class="line"><span>│ - Assigned tools/skills/MCP servers    │</span></span>
<span class="line"><span>│ - Handoff relationships                │</span></span>
<span class="line"><span>└────────────────────┬────────────────────┘</span></span>
<span class="line"><span>                     ↓</span></span>
<span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│ LLM processes the request                │</span></span>
<span class="line"><span>│ (using agent&#39;s context and constraints) │</span></span>
<span class="line"><span>└────────────────────┬────────────────────┘</span></span>
<span class="line"><span>                     ↓</span></span>
<span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│ Agent may:                              │</span></span>
<span class="line"><span>│ - Call tools directly                   │</span></span>
<span class="line"><span>│ - Handoff to another agent              │</span></span>
<span class="line"><span>│ - Ask for clarification                 │</span></span>
<span class="line"><span>│ - Return a result                       │</span></span>
<span class="line"><span>└────────────────────┬────────────────────┘</span></span>
<span class="line"><span>                     ↓</span></span>
<span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│ Result appears in your chat              │</span></span>
<span class="line"><span>└─────────────────────────────────────────┘</span></span></code></pre></div><h2 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design Principles&quot;">​</a></h2><p>Agent Studio is built on these principles:</p><p><strong>Clarity Over Configuration</strong></p><ul><li>Visual before textual</li><li>Discoverable before hidden</li><li>Explicit before implicit</li></ul><p><strong>Local-First</strong></p><ul><li>Your agents stay on your machine</li><li>Version controlled like code</li><li>No cloud dependency</li></ul><p><strong>Composition</strong></p><ul><li>Build complex systems from simple agents</li><li>Reuse tools, skills, and workflows</li><li>Extend through handoffs and capabilities</li></ul><p><strong>Standard Formats</strong></p><ul><li><code>.agent.md</code>: Human-readable agent definitions</li><li>MCP protocol: Standard external integrations</li><li><code>.json</code> for workflows: Portable, inspectable</li></ul><hr><p><strong><a href="./quick-start">← Quick Start</a></strong> | <strong><a href="./creating-agents">Creating Agents →</a></strong></p>`,67)])])}const h=e(i,[["render",l]]);export{u as __pageData,h as default};
